from ub import *
UNIT = mkunit("u115",
 ["memilih **kalimat yang menggambarkan foto** (Part 1) dengan pola present continuous dan passive",
  "menjawab **pertanyaan pendek** (Part 2) termasuk jawaban tidak langsung",
  "menghindari **jebakan bunyi mirip** dan jawaban yang salah jenis",
  "mengenali **tipe pertanyaan**: wh-, yes/no, pilihan, tag, dan permintaan"],
 [intro("**Part 1** menampilkan foto dan empat kalimat; kamu memilih yang paling cocok. **Part 2** memberi pertanyaan atau pernyataan pendek dan tiga pilihan jawaban. Kedua bagian menuntut telinga yang cepat dan kebiasaan membuang jawaban salah. Pada unit ini foto diganti **deskripsi gambar** dalam bahasa Indonesia."),
  gram("1. Part 1: pola kalimat deskripsi foto",
   table=[["Pola", "Contoh"],
          ["Orang melakukan sesuatu (present continuous)", "[[A man is opening a door.]]"],
          ["Benda dalam keadaan tertentu (passive continuous)", "[[Some boxes are being carried.]]"],
          ["Keadaan benda (present simple / passive)", "[[The books are stacked on the table.]]"],
          ["Letak benda (there is/are + preposisi)", "[[There are chairs around the table.]]"],
          ["Benda tampak (be + preposisi)", "[[A bicycle is leaning against the wall.]]"]],
   examples=[("[[Two women are shaking hands in an office.]]", "Dua wanita bersalaman di kantor.")]),
  warn("Jebakan Part 1", text="Pilihan yang menyebut hal yang **tidak tampak** (misalnya orang yang tidak ada, atau kegiatan yang tidak terjadi) salah. Jika foto hanya menampilkan benda, jawaban yang menyebut orang yang sedang melakukan sesuatu hampir pasti salah."),
  gram("2. Part 2: jenis pertanyaan dan jawaban",
   table=[["Pertanyaan", "Jawaban yang cocok", "Contoh"],
          ["**Who**", "nama atau jabatan", "[[Who is in charge? — Ms. Sari is.]]"],
          ["**When / What time**", "waktu", "[[When does it start? — At nine.]]"],
          ["**Where**", "tempat", "[[Where is the file? — On my desk.]]"],
          ["**Why**", "alasan", "[[Why was he late? — The train was delayed.]]"],
          ["**How much / How long**", "jumlah / durasi", "[[How long will it take? — About an hour.]]"],
          ["**Yes/No**", "Yes/No atau jawaban tidak langsung", "[[Did you send it? — I'll check right now.]]"],
          ["**Choice** (A or B)", "pilih salah satu", "[[Tea or coffee? — Coffee, please.]]"],
          ["**Request / Suggestion**", "setuju / menolak sopan", "[[Could you help me? — Sure, no problem.]]"]]),
  gram("3. Jebakan bunyi dan jawaban tidak langsung",
   table=[["Jebakan", "Contoh"],
          ["Kata mirip bunyi", "*Where is the **meeting**?* — *I'll **eat** now.* (tidak menjawab)"],
          ["Mengulang kata dari pertanyaan", "*Did you **send** the report?* — *I **sent** my friend a gift.* (tidak relevan)"],
          ["Jawaban Yes/No pada pertanyaan wh-", "*Where is the file?* — *Yes, it is.* (salah)"],
          ["Jawaban tidak langsung (benar)", "*Is the meeting at three?* — *Let me check my schedule.*"]]),
  tip("Dengarkan awal pertanyaan", text="Tangkap **kata tanya** (who, when, where, why, how) lebih dulu, lalu cocokkan jenis jawaban. Buang pilihan yang jenisnya salah, misalnya jawaban waktu untuk pertanyaan tempat."),
  summary(["Part 1: present continuous / passive; buang pilihan yang menyebut hal yang tidak tampak.", "Part 2: cocokkan kata tanya dengan jenis jawaban.", "Wh-question tidak dijawab Yes/No.", "Jawaban tidak langsung sering benar: *Let me check.*", "Waspadai kata yang bunyinya mirip."])],
 [], [])
def foto(desc, correct, wrong, exp):
    return mcq(f'Foto: {desc}. Kalimat mana yang paling cocok?', [correct] + wrong, 0, exp)
P = [
 foto('seorang pria sedang membuka pintu kantor', 'A man is opening a door.', ['A man is closing a window.', 'Some people are waiting in line.', 'A woman is answering a phone.'], 'Sesuai gambar: membuka pintu.'),
 foto('dua wanita bersalaman di ruang rapat', 'Two women are shaking hands.', ['Two women are drinking coffee.', 'Some men are writing on a board.', 'The women are walking outside.'], 'Bersalaman.'),
 foto('beberapa kotak ditumpuk di gudang, tidak ada orang', 'Some boxes are stacked in a warehouse.', ['A man is carrying a box.', 'Workers are loading a truck these days.', 'A woman is counting boxes these days.'], 'Tidak ada orang di foto.'),
 foto('seorang wanita sedang menulis di papan tulis di depan kelas', 'A woman is writing on a board.', ['A woman is reading a newspaper.', 'Students are leaving the room.', 'A man is cleaning the floor.'], 'Menulis di papan.'),
 foto('beberapa orang mengantre di loket tiket', 'People are standing in line at a counter.', ['People are sitting in a restaurant.', 'A man is repairing a machine this week.', 'Some passengers are boarding a plane as usual.'], 'Mengantre.'),
 foto('sebuah sepeda bersandar pada dinding, tidak ada orang', 'A bicycle is leaning against a wall.', ['A man is riding a bicycle.', 'A woman is repairing a bicycle.', 'Two children are pushing a bicycle.'], 'Tidak ada orang.'),
 foto('seorang pria sedang menggunakan komputer di mejanya', 'A man is working at a computer.', ['A man is talking on the phone.', 'A man is leaving the office.', 'A woman is taking a photograph.'], 'Menggunakan komputer.'),
 foto('beberapa kursi diatur mengelilingi meja bundar', 'Chairs are arranged around a table.', ['People are eating at the table.', 'A man is moving the table.', 'A woman is cleaning the chairs.'], 'Letak benda.'),
 foto('seorang pelayan menuangkan kopi ke cangkir pelanggan', 'A waiter is pouring coffee.', ['A customer is paying the bill.', 'A cook is chopping vegetables.', 'The waiter is carrying plates.'], 'Menuangkan kopi.'),
 foto('beberapa pekerja memakai helm sedang mengangkat balok', 'Workers are lifting some beams.', ['Workers are drinking water.', 'A man is reading a map.', 'People are sitting in a meeting.'], 'Mengangkat balok.'),
 foto('seorang wanita memegang dokumen sambil berdiri di dekat mesin fotokopi', 'A woman is holding some papers.', ['A woman is buying a ticket.', 'A woman is writing a letter.', 'A woman is washing some cups.'], 'Memegang dokumen.'),
 foto('sebuah kapal bersandar di dermaga, tidak ada orang', 'A boat is docked at a pier.', ['A man is fishing from a boat.', 'People are boarding a boat.', 'A woman is swimming.'], 'Tidak ada orang.'),
]
def q2(question, ans, w1, w2, exp):
    return listen('Dengarkan pertanyaan. Pilih jawaban terbaik.', question, [ans, w1, w2], 0, exp)
P += [
 q2('Where is the meeting room?', 'On the second floor.', 'At three o\'clock.', 'Yes, it is.', 'Where → tempat.'),
 q2('When does the train leave?', 'At nine thirty.', 'In the station.', 'It is very fast.', 'When → waktu.'),
 q2('Who is in charge of the project?', 'Ms. Sari is.', 'Next Monday.', 'In the office.', 'Who → orang.'),
 q2('Why was the flight delayed?', 'Because of bad weather.', 'At the airport.', 'About two hours.', 'Why → alasan.'),
 q2('How long will the meeting take?', 'About an hour.', 'In the conference room.', 'Mr. Adi will attend.', 'How long → durasi.'),
 q2('How much is this laptop?', 'It is five hundred dollars.', 'It is on the table.', 'Yes, it works well.', 'How much → harga.'),
 q2('Did you send the report?', 'Yes, this morning.', 'On the desk.', 'At two o\'clock.', 'Yes/No question.'),
 q2('Would you like tea or coffee?', 'Coffee, please.', 'Yes, I would.', 'At the cafe.', 'Pilihan → pilih satu.'),
 q2('Could you help me with this box?', 'Sure, no problem.', 'It is heavy.', 'On the floor.', 'Permintaan → setuju.'),
 q2('Shall we start the meeting now?', 'Let\'s wait for Mr. Adi.', 'In the meeting room.', 'It is a long meeting.', 'Saran → tanggapan.'),
 q2('Is the printer broken?', 'I think so; let me check.', 'It is on the second floor.', 'At nine o\'clock.', 'Jawaban tidak langsung.'),
 q2('You have the key, don\'t you?', 'Yes, I do.', 'On the table.', 'At the door.', 'Tag question.'),
 q2('What time does the store open?', 'At ten o\'clock.', 'It is a new store.', 'In the mall.', 'What time → jam.'),
 q2('Where can I find the manager?', 'He is in his office.', 'He is very tall.', 'At five o\'clock.', 'Where → tempat.'),
 q2('Who should I call about the invoice?', 'The accounting department.', 'Next week.', 'It is on the desk.', 'Who → pihak.'),
 q2('Why don\'t we order lunch?', 'That\'s a good idea.', 'At the restaurant.', 'On Friday.', 'Saran → setuju.'),
 q2('When is the deadline for the report?', 'This Friday.', 'In the office.', 'It is very long.', 'When → waktu.'),
 q2('Do you know where the stapler is?', 'It is in the drawer.', 'Yes, it is a good one.', 'I stapled it yesterday.', 'Jawab lokasi.'),
 q2('Which room is the meeting in?', 'The one on the left.', 'At eleven thirty.', 'It is about sales.', 'Which → pilih.'),
 q2('How did the interview go?', 'It went very well.', 'In room two.', 'At three o\'clock.', 'How → cara/hasil.'),
]
Q = [
 foto('seorang pria sedang menaiki tangga di dalam kantor', 'A man is climbing some stairs.', ['A man is sitting at a desk.', 'Some people are waiting for a bus.', 'A woman is painting a wall.'], 'Menaiki tangga.'),
 foto('beberapa mobil diparkir berjajar di depan gedung, tidak ada orang', 'Some cars are parked in a row.', ['People are getting into cars.', 'A man is washing a car.', 'A woman is driving a truck.'], 'Tidak ada orang.'),
 q2('Where is the nearest bank?', 'Down the street.', 'At four o\'clock.', 'Yes, it is.', 'Where → tempat.'),
 q2('When will the package arrive?', 'Tomorrow morning.', 'In the warehouse.', 'It is heavy.', 'When → waktu.'),
 q2('Who made the reservation?', 'Mr. Adi did.', 'For two people.', 'At seven o\'clock.', 'Who → orang.'),
 q2('Can I use your pen?', 'Of course, here you are.', 'It is blue.', 'In my bag.', 'Permintaan → setuju.'),
 q2('Would you prefer the window or the aisle seat?', 'The window, please.', 'Yes, I would.', 'On the plane.', 'Pilihan.'),
 q2('Why did you call the supplier?', 'To check the delivery date.', 'Yes, I did.', 'At the office.', 'Why → tujuan.'),
]
UNIT["practice"] = P
UNIT["quiz"] = Q
